(function() {
    'use strict';

    class NarrativeCraftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'NarrativeCraft: Business Storytelling';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    key: 'board',
                    nameKey: 'round_board',
                    nameDefault: 'Board Executive Summary',
                    briefing: '<strong>Round 1: Board of Directors</strong><br><br>Luminary Software closed the fiscal year with ARR of €53.9M (28% YoY growth), missing board guidance of 35%. Gross margin compressed from 71% to 66%. Net revenue retention rose to 108%. Luminary Predict launched 6 weeks late but hit 62% enterprise adoption in 90 days.<br><br>The board has already seen the raw data. They are assessing whether leadership interpretation and response are credible, strategic, and honest.<br><br><strong>Your task:</strong> Construct a SCQA executive summary with visualization choices. The board values logical structure, intellectual honesty, and a forward-looking action plan.'
                },
                {
                    key: 'employee',
                    nameKey: 'round_employee',
                    nameDefault: 'All-Hands Employee Communication',
                    briefing: '<strong>Round 2: All-Hands Meeting (390 Employees)</strong><br><br>Employees know the company missed guidance through informal channels. They do not know the magnitude. Anxiety is elevated after 18 contractor eliminations and two executive departures. Engineering morale is low following the Predict launch delay.<br><br>Employee engagement dropped from 78 to 71 (engineering: 76 to 63). CEO Mara Osei will present. Q&A is live. Attendance is mandatory.<br><br><strong>Your task:</strong> Calibrate emotional tone and prepare direct, specific responses to three challenge questions. Employees detect deflection faster than any other audience.'
                },
                {
                    key: 'media',
                    nameKey: 'round_media',
                    nameDefault: 'Media Message House',
                    briefing: '<strong>Round 3: Media Interview (Senior Tech Journalist)</strong><br><br>A journalist from a leading B2B publication has requested a 30-minute interview. They have independently sourced the ARR growth rate and the Predict delay. They are deciding between a "SaaS slowdown" story and a "resilient AI-native business" story.<br><br>They will publish regardless of participation. The only question is how much narrative Luminary shapes.<br><br><strong>Your task:</strong> Build a message house with specific, verifiable claims. Design bridge phrases that acknowledge before redirecting. Craft a credible response to the hostile financial question.'
                }
            ];

            this.RANDOM_EVENTS = [
                { id: 1, text: 'A Glassdoor review claiming "quiet layoff plans in engineering" has 47 upvotes and is circulating on internal Slack. Employee anxiety threshold is now higher.', effect: 'employee_anxiety_up' },
                { id: 2, text: 'The Series C lead investor has requested an "urgent board call" before the all-hands, signaling heightened investor concern.', effect: 'board_credibility_up' },
                { id: 3, text: 'The journalist tweeted: "Sources say @LuminarySW missed growth guidance by 7 points." The real miss is 5.1 points. You must decide how to handle the inaccuracy.', effect: 'media_correction' },
                { id: 4, text: 'Singapore engineering lead messaged the CEO: "The team is demoralized. If the all-hands message is wrong, I cannot prevent departures."', effect: 'engineering_morale' },
                { id: 5, text: 'A competitor announced 40% revenue growth in the same fiscal year, trending on LinkedIn among Luminary employees.', effect: 'competitor_benchmark' },
                { id: 6, text: 'No complication this session. Proceed under baseline conditions.', effect: 'none' }
            ];

            this.VIZ_SCORES = {
                1:  { accuracy: 8, framing: 0, ethos: 3, ethics: 0 },
                2:  { accuracy: 2, framing: 5, ethos: -2, ethics: -10 },
                3:  { accuracy: 8, framing: 8, ethos: 5, ethics: 0 },
                4:  { accuracy: 8, framing: 6, ethos: 4, ethics: 0 },
                5:  { accuracy: 8, framing: 3, ethos: 5, ethics: 0 },
                6:  { accuracy: 7, framing: -2, ethos: 2, ethics: 0 },
                7:  { accuracy: 8, framing: 2, ethos: 4, ethics: 0 },
                8:  { accuracy: 3, framing: -1, ethos: -3, ethics: -2 },
                9:  { accuracy: 8, framing: 7, ethos: 5, ethics: 0 },
                10: { accuracy: 7, framing: 3, ethos: 3, ethics: 0 },
                11: { accuracy: 8, framing: 4, ethos: 5, ethics: 0 },
                12: { accuracy: 7, framing: 2, ethos: 2, ethics: 0 }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalCES: 0,
                    boardCES: 0,
                    employeeCES: 0,
                    mediaCES: 0,
                    credibility: 100,
                    audienceTrust: 100,
                    ethicsScore: 100,
                    logosHistory: [],
                    ethosHistory: [],
                    pathosHistory: [],
                    ethicsHistory: [],
                    cesHistory: [],
                    randomEvent: 0,
                    consistencyBonus: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    scqaLead: 1,
                    govThought: 1,
                    missAttr: 3,
                    marginTreat: 1,
                    viz1: 3,
                    viz2: 9,
                    emotCal: 5,
                    layoffDir: 3,
                    layoffSpec: 3,
                    targetDir: 3,
                    targetSpec: 3,
                    predictDir: 3,
                    predictSpec: 3,
                    msgSpec: 5,
                    bridgeStrat: 1,
                    hostileResp: 2
                };
            }
            this._updateBriefing(state);
            this._setupRangeListeners();
            this._registerLifecycle();
        }

        _writeScore(ds, score) {
            var s = Math.max(0, Math.min(100, Math.round(score || 0)));
            if (!ds.performance || typeof ds.performance !== 'object') { ds.performance = {}; }
            ds.performance.overallScore = s;
            ds.score = s;
            return s;
        }

        _registerLifecycle() {
            var self = this;
            try {
                var sim = window.mySimulation;
                if (sim && sim.periodManager && typeof sim.periodManager.addHook === 'function') {
                    sim.periodManager.addHook('afterAdvance', function(st) { try { self._updateBriefing(st); } catch (e) {} });
                }
                if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                    sim.eventBus.on('period:undone', function(st) { try { self._updateBriefing(st); } catch (e) {} });
                }
            } catch (e) {}
        }

        _setupRangeListeners() {
            var ranges = [
                { input: 'emotCalInput', display: 'emotCalDisplay' },
                { input: 'layoffDirInput', display: 'layoffDirDisplay' },
                { input: 'layoffSpecInput', display: 'layoffSpecDisplay' },
                { input: 'targetDirInput', display: 'targetDirDisplay' },
                { input: 'targetSpecInput', display: 'targetSpecDisplay' },
                { input: 'predictDirInput', display: 'predictDirDisplay' },
                { input: 'predictSpecInput', display: 'predictSpecDisplay' },
                { input: 'msgSpecInput', display: 'msgSpecDisplay' }
            ];
            ranges.forEach(function(r) {
                var el = document.getElementById(r.input);
                var disp = document.getElementById(r.display);
                if (el && disp) {
                    el.addEventListener('input', function() { disp.textContent = el.value; });
                }
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            var roundNameEl = document.getElementById('roundName');
            if (roundNameEl) {
                var translated = window.mySimulation ? window.mySimulation.t(round.nameKey) : null;
                roundNameEl.textContent = translated || round.nameDefault;
            }

            var boardPanel = document.getElementById('boardPanel');
            var employeePanel = document.getElementById('employeePanel');
            var mediaPanel = document.getElementById('mediaPanel');

            if (boardPanel) boardPanel.style.display = idx === 0 ? 'block' : 'none';
            if (employeePanel) employeePanel.style.display = idx === 1 ? 'block' : 'none';
            if (mediaPanel) mediaPanel.style.display = idx === 2 ? 'block' : 'none';

            if (idx === 1 && state.domainState && state.domainState.randomEvent === 0) {
                var eventRoll = Math.floor(Math.random() * 6) + 1;
                state.domainState.randomEvent = eventRoll;
            }

            if (idx >= 1 && state.domainState && state.domainState.randomEvent > 0 && state.domainState.randomEvent < 6) {
                var evt = this.RANDOM_EVENTS[state.domainState.randomEvent - 1];
                var banner = document.getElementById('eventBanner');
                var eventText = document.getElementById('eventText');
                if (banner) banner.style.display = 'block';
                if (eventText) eventText.innerHTML = evt.text;
            } else {
                var bannerEl = document.getElementById('eventBanner');
                if (bannerEl) bannerEl.style.display = 'none';
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var scqa = document.getElementById('scqaLeadInput');
                var gov = document.getElementById('govThoughtInput');
                var miss = document.getElementById('missAttrInput');
                var margin = document.getElementById('marginInput');
                var v1 = document.getElementById('viz1Input');
                var v2 = document.getElementById('viz2Input');
                if (scqa) decisions.scqaLead = parseInt(scqa.value);
                if (gov) decisions.govThought = parseInt(gov.value);
                if (miss) decisions.missAttr = parseInt(miss.value);
                if (margin) decisions.marginTreat = parseInt(margin.value);
                if (v1) decisions.viz1 = parseInt(v1.value);
                if (v2) decisions.viz2 = parseInt(v2.value);

                if (decisions.viz1 === decisions.viz2) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('viz_same_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var ec = document.getElementById('emotCalInput');
                if (ec) decisions.emotCal = parseInt(ec.value);
                var ld = document.getElementById('layoffDirInput');
                if (ld) decisions.layoffDir = parseInt(ld.value);
                var ls = document.getElementById('layoffSpecInput');
                if (ls) decisions.layoffSpec = parseInt(ls.value);
                var td = document.getElementById('targetDirInput');
                if (td) decisions.targetDir = parseInt(td.value);
                var ts = document.getElementById('targetSpecInput');
                if (ts) decisions.targetSpec = parseInt(ts.value);
                var pd = document.getElementById('predictDirInput');
                if (pd) decisions.predictDir = parseInt(pd.value);
                var ps = document.getElementById('predictSpecInput');
                if (ps) decisions.predictSpec = parseInt(ps.value);
            } else if (period === 3) {
                var ms = document.getElementById('msgSpecInput');
                if (ms) decisions.msgSpec = parseInt(ms.value);
                var br = document.getElementById('bridgeInput');
                if (br) decisions.bridgeStrat = parseInt(br.value);
                var hr = document.getElementById('hostileInput');
                if (hr) decisions.hostileResp = parseInt(hr.value);
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var logos = 0;
            var ethos = 0;
            var pathos = 0;
            var ethics = 0;
            var ces = 0;
            var roundLabel = '';

            if (period === 1) {
                roundLabel = 'Board';

                if (d.scqaLead === 1) { ethos += 8; logos += 6; }
                else if (d.scqaLead === 2) { ethos -= 5; logos += 3; }
                else { ethos += 2; logos += 5; }

                if (d.govThought === 1) { logos += 10; ethos += 5; }
                else if (d.govThought === 2) { logos -= 4; ethos -= 4; }
                else { logos += 5; ethos += 2; }

                if (d.missAttr === 3) { ethos += 9; ethics += 5; logos += 4; }
                else if (d.missAttr === 1) { ethos -= 6; ethics -= 3; }
                else { ethos -= 2; logos += 2; }

                if (d.marginTreat === 1) { ethos += 4; ethics += 5; logos += 3; }
                else if (d.marginTreat === 2) { ethos += 1; ethics += 2; }
                else { ethics -= 12; ethos -= 6; }

                var v1s = this.VIZ_SCORES[d.viz1] || { accuracy: 0, framing: 0, ethos: 0, ethics: 0 };
                var v2s = this.VIZ_SCORES[d.viz2] || { accuracy: 0, framing: 0, ethos: 0, ethics: 0 };
                logos += Math.round((v1s.accuracy + v2s.accuracy) / 2);
                ethos += Math.round((v1s.ethos + v2s.ethos) / 2);
                pathos += Math.round((v1s.framing + v2s.framing) / 2);
                ethics += Math.round((v1s.ethics + v2s.ethics) / 2);

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.35 + ethos * 0.30 + pathos * 0.15 + ethics * 0.20);
                ds.boardCES = ces;

            } else if (period === 2) {
                roundLabel = 'Employee';

                var ecVal = d.emotCal;
                if (ecVal >= 4 && ecVal <= 6) { pathos += 10; ethos += 5; }
                else if (ecVal >= 7 && ecVal <= 9) { ethos -= 8; pathos -= 3; }
                else if (ecVal === 10) { ethos -= 15; pathos -= 10; ethics -= 8; }
                else if (ecVal <= 3) { pathos += 4; ethos += 3; logos += 2; }

                var qaDirs = [d.layoffDir, d.targetDir, d.predictDir];
                var qaSpecs = [d.layoffSpec, d.targetSpec, d.predictSpec];
                var qaLogos = 0;
                var qaEthos = 0;
                var qaPathos = 0;

                for (var i = 0; i < 3; i++) {
                    if (qaDirs[i] >= 4) { qaEthos += 6; qaPathos += 4; }
                    else if (qaDirs[i] <= 2) { qaEthos -= 8; qaPathos -= 5; }
                    else { qaEthos += 1; }

                    if (qaSpecs[i] >= 4) { qaLogos += 5; qaEthos += 3; }
                    else if (qaSpecs[i] <= 2) { qaLogos -= 3; }
                    else { qaLogos += 1; }
                }

                logos += qaLogos;
                ethos += qaEthos;
                pathos += qaPathos;

                var evtId = ds.randomEvent || 6;
                if (evtId === 1) { pathos -= 5; ethos -= 3; }
                else if (evtId === 4) { pathos -= 7; }
                else if (evtId === 5) { ethos -= 4; }

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.20 + ethos * 0.25 + pathos * 0.40 + ethics * 0.15);
                ds.employeeCES = ces;

            } else if (period === 3) {
                roundLabel = 'Media';

                var specScore = d.msgSpec;
                ethos += specScore * 2;
                logos += Math.round(specScore * 1.2);

                if (d.bridgeStrat === 1) { ethos += 10; ethics += 5; logos += 3; }
                else if (d.bridgeStrat === 2) { ethos -= 12; ethics -= 8; }
                else { ethos -= 6; ethics -= 3; }

                if (d.hostileResp === 2) { ethos += 12; ethics += 6; logos += 5; pathos += 4; }
                else if (d.hostileResp === 1) { ethos -= 10; ethics -= 5; pathos -= 3; }
                else { ethos += 2; logos += 3; pathos += 2; ethics += 1; }

                var mEvt = ds.randomEvent || 6;
                if (mEvt === 3) { ethos -= 5; }

                logos = Math.max(0, Math.min(100, 50 + logos));
                ethos = Math.max(0, Math.min(100, 50 + ethos));
                pathos = Math.max(0, Math.min(100, 50 + pathos));
                ethics = Math.max(0, Math.min(100, 70 + ethics));

                ces = Math.round(logos * 0.25 + ethos * 0.35 + pathos * 0.20 + ethics * 0.20);
                ds.mediaCES = ces;
            }

            ds.logosHistory.push(logos);
            ds.ethosHistory.push(ethos);
            ds.pathosHistory.push(pathos);
            ds.ethicsHistory.push(ethics);
            ds.cesHistory.push(ces);

            ds.totalCES = Math.round(ds.cesHistory.reduce(function(s, v) { return s + v; }, 0) / ds.cesHistory.length);

            if (period === 3 && ds.boardCES >= 70 && ds.employeeCES >= 70 && ds.mediaCES >= 70) {
                ds.consistencyBonus = 15;
                ds.totalCES = Math.min(100, ds.totalCES + ds.consistencyBonus);
            }

            ds.credibility = Math.round((ds.cesHistory.reduce(function(s, v) { return s + v; }, 0) / ds.cesHistory.length) * 0.8 + (ethics * 0.2));
            ds.audienceTrust = Math.round(ethos * 0.5 + pathos * 0.3 + ethics * 0.2);
            ds.ethicsScore = Math.round(ds.ethicsHistory.reduce(function(s, v) { return s + v; }, 0) / ds.ethicsHistory.length);

            this._writeScore(ds, ds.totalCES);

            return {
                period: period,
                roundLabel: roundLabel,
                logos: logos,
                ethos: ethos,
                pathos: pathos,
                ethics: ethics,
                ces: ces,
                credibility: ds.credibility,
                trust: ds.audienceTrust,
                totalCES: ds.totalCES,
                consistencyBonus: ds.consistencyBonus,
                overallScore: ds.totalCES
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cesDisplay', 'domainState.totalCES',
                function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('credibilityDisplay', 'domainState.credibility',
                function(v) { return Math.round(v); });
            uiManager.bind('trustDisplay', 'domainState.audienceTrust',
                function(v) { return Math.round(v); });
            uiManager.bind('ethicsDisplay', 'domainState.ethicsScore',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                cesChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'CES Score',
                            data: [],
                            backgroundColor: ['rgba(52,152,219,0.7)', 'rgba(46,204,113,0.7)', 'rgba(155,89,182,0.7)'],
                            borderColor: ['#3498db', '#2ecc71', '#9b59b6'],
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Communication Effectiveness by Round' } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                },
                dimensionChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Logos', data: [], borderColor: '#3498db', backgroundColor: 'rgba(52,152,219,0.1)', borderWidth: 2, fill: false, tension: 0.2 },
                            { label: 'Ethos', data: [], borderColor: '#2ecc71', backgroundColor: 'rgba(46,204,113,0.1)', borderWidth: 2, fill: false, tension: 0.2 },
                            { label: 'Pathos', data: [], borderColor: '#e74c3c', backgroundColor: 'rgba(231,76,60,0.1)', borderWidth: 2, fill: false, tension: 0.2 },
                            { label: 'Ethics', data: [], borderColor: '#f39c12', backgroundColor: 'rgba(243,156,18,0.1)', borderWidth: 2, fill: false, tension: 0.2 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Persuasion Dimensions by Round' } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var roundLabels = ['Board', 'Employee', 'Media'];
            var labels = state.domainState.cesHistory.map(function(_, i) { return roundLabels[i] || ('R' + (i + 1)); });
            return {
                cesChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.cesHistory }]
                },
                dimensionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.logosHistory },
                        { data: state.domainState.ethosHistory },
                        { data: state.domainState.pathosHistory },
                        { data: state.domainState.ethicsHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var cesScores = history.map(function(r) { return r.results ? r.results.ces : 0; });
            var totalCES = cesScores.reduce(function(s, v) { return s + v; }, 0);
            var avgCES = Math.round(totalCES / cesScores.length);
            var bonus = 0;

            if (history.length === 3) {
                var allAbove70 = cesScores.every(function(c) { return c >= 70; });
                if (allAbove70) bonus = 15;
            }

            var finalScore = Math.min(100, avgCES + bonus);
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var performance = T('perf_fail');
            if (finalScore >= 85) performance = T('perf_trusted');
            else if (finalScore >= 70) performance = T('perf_competent');
            else if (finalScore >= 55) performance = T('perf_inconsistent');
            else if (finalScore >= 40) performance = T('perf_gap');

            var insights = [];
            if (finalScore >= 85) insights.push(T('insight_85'));
            else if (finalScore >= 70) insights.push(T('insight_70'));
            else if (finalScore >= 55) insights.push(T('insight_55'));
            else if (finalScore >= 40) insights.push(T('insight_40'));
            else insights.push(T('insight_fail'));

            if (bonus > 0) insights.push(T('insight_bonus'));

            return {
                totalCES: finalScore,
                avgCES: avgCES,
                consistencyBonus: bonus,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.ces < 50) return window.mySimulation.t('hint_low_ces');
            if (results.ethics < 60) return window.mySimulation.t('hint_ethics_risk');
            if (results.ethos < 55) return window.mySimulation.t('hint_credibility');
            if (results.ces >= 75) return window.mySimulation.t('hint_strong');
            return null;
        }

